import re


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    Tag names are matched case-insensitively. The text is returned exactly
    as it appears, with no whitespace stripping or entity decoding.
    Returns "" if there is no `<title>` or no closing `</title>` after it.
    Does not access the network.
    """
    m = re.search(
        r"<title>(.*?)</title>",
        html,
        re.IGNORECASE | re.DOTALL | re.ASCII,
    )
    return m.group(1) if m else ""


def test_basic() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_unclosed_title() -> None:
    assert title_of("<html><title>Oops</html>") == ""


def test_closing_tag_only() -> None:
    assert title_of("</title>") == ""


def test_closing_before_opening() -> None:
    assert title_of("</title><title>x</title>") == "x"


def test_case_insensitive() -> None:
    assert title_of("<TITLE>Upper</TITLE>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_first_title_only() -> None:
    assert title_of("<title>A</title><title>B</title>") == "A"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced \n out  </title>") == "  spaced \n out  "


def test_multiline_title() -> None:
    assert title_of("<title>\nLine one\nLine two\n</title>") == "\nLine one\nLine two\n"


def test_entities_not_decoded() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_unicode() -> None:
    assert title_of("<title>Zürich — café ☕</title>") == "Zürich — café ☕"
